# Generated by `shiny theme new` from shiny-hansel.png
# Base scheme: Nightfox — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely; `shiny theme set <name>` re-applies.
THEME_BASE="Nightfox"
GHOSTTY_THEME="Nightfox"   # built-in: ghostty +list-themes
ACCENT_PRESET=4                    # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#192330"         # window background
BG_DARK="#141D27"    # frames, omnibox
SURFACE="#2B3440"    # borders, dividers, inactive window border
SELECTION="#2B3B51"  # selected rows, text selection
MUTED="#4B535D"      # shortcuts, scrollbar
COMMENT="#656B73"    # subtext, inactive tabs
FG="#CDCECF"         # primary text
FG_DIM="#ADAFB2"     # secondary text
ACCENT="#86ABDC"     # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#F4A261"    # secondary accent: cursor, shortcuts, search selection
